  if (!d) return out;
  out.add(d);
  if (d.length === 10) out.add('91' + d);
  if (d.startsWith('91') && d.length === 12) out.add(d.slice(2));
  if (d.startsWith('0') && d.length === 11) {
    out.add(d.slice(1));
    out.add('91' + d.slice(1));
  }
  return out;
}

