const aiBody = String((aiOut && aiOut.body) || '').trim();
const subject = aiSubject || ('Follow-up from ' + client);
const body = aiBody || [
  'Hi ' + name + ',',
  '',
  'Thank you for speaking with us' + (about ? ' about ' + about : '') + '.',
